/*
 * Copies the embedded examples into the app as string constants.
 *
 * The simulator page shows the real firmware source. It could import those
 * files with vite's `?raw`, and that was the first attempt, but rollup
 * would not resolve a `.ino` across the workspace boundary and the whole
 * page then depends on one bundler's resolution rules for an extension it
 * has no opinion about.
 *
 * So this generates instead, which is the idiom this repository already
 * uses twice: src/kernel/worklet-code.gen.ts and public/llm.txt are both
 * checked-in generated files with a CI step that regenerates and diffs. The
 * same step guards this one, so the page cannot drift from the examples it
 * claims to show.
 *
 *   node scripts/gen-firmware-sources.mjs
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const app = join(here, '..');
const examples = join(app, '../../packages/bellows-embedded/examples');

/* Every file the page shows. Keep in step with FIRMWARES in firmware.ts:
 * a missing key is a build error there, which is the point. */
const FILES = {
  onekick_h: '01_OneKick/onekick.h',
  onekick_ino: '01_OneKick/01_OneKick.ino',
  drummachine_h: '02_DrumMachine/drummachine.h',
  drummachine_ino: '02_DrumMachine/02_DrumMachine.ino',
  polysynth_h: '03_PolySynth/polysynth.h',
  polysynth_ino: '03_PolySynth/03_PolySynth.ino',
  scalestuning_h: '04_ScalesAndTuning/scalestuning.h',
  scalestuning_ino: '04_ScalesAndTuning/04_ScalesAndTuning.ino',
  audioshield_h: '10_AudioShield/audioshield.h',
  audioshield_ino: '10_AudioShield/10_AudioShield.ino',
  piezo_h: '15_Piezo/piezo.h',
  piezo_ino: '15_Piezo/15_Piezo.ino',
};

const parts = [
  '/* Generated by scripts/gen-firmware-sources.mjs. Do not edit by hand.',
  ' *',
  ' * The embedded examples, verbatim, so the simulator shows the source that',
  ' * compiles to a board rather than a copy of it. Regenerate after changing',
  ' * anything under packages/bellows-embedded/examples; CI regenerates and',
  ' * diffs, so a stale copy fails the build rather than misleading a reader.',
  ' */',
  '',
];

let bytes = 0;
for (const [key, rel] of Object.entries(FILES)) {
  const text = readFileSync(join(examples, rel), 'utf8');
  bytes += text.length;
  parts.push(`export const ${key}: string = ${JSON.stringify(text)};`);
  parts.push('');
}

writeFileSync(join(app, 'src/lib/sim/sources.gen.ts'), parts.join('\n'));
console.log(
  `sources.gen.ts written: ${Object.keys(FILES).length} files, ${(bytes / 1024).toFixed(1)} KB`,
);
